import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"Repo Split Readiness","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/split-readiness.md","filePath":"architecture/split-readiness.md","lastUpdated":1780254295000}'),n={name:"architecture/split-readiness.md"};function r(d,e,i,c,l,p){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="repo-split-readiness" tabindex="-1">Repo Split Readiness <a class="header-anchor" href="#repo-split-readiness" aria-label="Permalink to &quot;Repo Split Readiness&quot;">​</a></h1><p>This document tracks what a future split of the monorepo into separate backend and desktop repos would actually require, post-architectural-collapse and post-Tauri-migration. The collapse resolved many of the original blockers; the Tauri migration changed the remaining backend↔desktop coupling (the desktop now embeds the Rust crates directly in its <code>src-tauri</code> host rather than through a prebuilt napi addon).</p><h2 id="status-deferred-not-blocked" tabindex="-1">Status: deferred, not blocked <a class="header-anchor" href="#status-deferred-not-blocked" aria-label="Permalink to &quot;Status: deferred, not blocked&quot;">​</a></h2><p>The split is <strong>not</strong> on any roadmap right now. The collapse removed most of the original coupling — there is no shared proto SDK, no cross-product packaging CLI, no daemon/agent gRPC contract surface between backend and desktop. The remaining coupling is narrow enough that a split would be a mechanical move, not an architectural project.</p><h2 id="why-most-of-the-old-blockers-are-gone" tabindex="-1">Why most of the old blockers are gone <a class="header-anchor" href="#why-most-of-the-old-blockers-are-gone" aria-label="Permalink to &quot;Why most of the old blockers are gone&quot;">​</a></h2><p>Pre-collapse, the split was blocked by:</p><table tabindex="0"><thead><tr><th>Blocker (pre-collapse)</th><th>Status now</th></tr></thead><tbody><tr><td>Shared <code>proto/</code> source consumed by both Rust and TypeScript</td><td>Resolved. <code>proto/</code> is now used only for libp2p wire formats (Rust-only). <code>desktop/desktop-proto</code> (<code>@soma/proto</code>) was removed with the Electron app; the renderer&#39;s TypeScript wire types are generated from the Rust command graph via <code>tauri-specta</code> into <code>@soma/sdk</code>.</td></tr><tr><td>Daemon/agent IPC contracts consumed by desktop</td><td>Resolved. The Tauri <code>src-tauri</code> host embeds the <code>soma-daemon</code> / <code>soma-agentd</code> crates as libraries (via <code>desktop-daemon</code> / <code>desktop-agent</code>) and calls them in-process. No gRPC, no Unix sockets, no napi addon; the renderer talks to the host over Tauri commands (<code>@soma/sdk</code>).</td></tr><tr><td><code>desktop/packaging</code> CLI assuming one repo namespace</td><td>Resolved. <code>desktop/packaging</code> was deleted in P6a. Packaging is now per-artifact: the <strong>Tauri bundler</strong> for the desktop app, the multi-arch <code>Dockerfile</code> for <code>somad</code>. No cross-product bundler.</td></tr><tr><td>Release manifest schema for cross-repo discovery</td><td>No longer needed. Desktop assets are published to <code>desktop-v*</code> Releases (with <code>SHA256SUMS</code>); the server image is published to <code>ghcr.io/&lt;owner&gt;/somad</code>. Each release stands alone.</td></tr><tr><td><code>release.yml</code> orchestrating both backend and desktop</td><td>Resolved. <code>release-desktop.yml</code> and <code>release-server.yml</code> are independent, each driven by <code>.github/targets.json</code>.</td></tr><tr><td>Install/uninstall bootstrap scripts coupling release URLs</td><td>Resolved. Retired in P6a; users download directly from GitHub Releases.</td></tr></tbody></table><h2 id="what-s-actually-left" tabindex="-1">What&#39;s actually left <a class="header-anchor" href="#what-s-actually-left" aria-label="Permalink to &quot;What&#39;s actually left&quot;">​</a></h2><p>The remaining coupling between <code>backend/</code> and <code>desktop/</code> after the collapse:</p><ul><li><strong>Shared Cargo workspace link.</strong> The Tauri host (<code>desktop/desktop-app/src-tauri</code> + the <code>desktop-*</code> crates) depends on the backend runtime crates (<code>soma-daemon</code>, <code>soma-agentd</code>, and their dependencies) as path dependencies in the root Cargo workspace. In a split, the desktop repo would need those crates published (e.g. to a private registry) or vendored, and the desktop&#39;s <code>src-tauri</code> build would consume them as versioned dependencies rather than path deps.</li><li><strong><code>.github/targets.json</code> shared (os, arch) source.</strong> Lives at the repo root, consumed by both release workflows. Trivially duplicated or factored to a shared action if split.</li><li><strong>Single <code>docs/</code> VitePress site.</strong> Architecture, development, and security docs cover both products. A split would need to decide: one shared docs repo, or per-product docs with separate sites.</li><li><strong>Root pnpm/Cargo workspace files.</strong> <code>Cargo.toml</code>, <code>pnpm-workspace.yaml</code>, <code>package.json</code> at the root would dissolve into per-repo equivalents.</li><li><strong><code>xtask/</code> lives at the repo root</strong> alongside <code>backend/</code>. Trivially moves with backend.</li></ul><h2 id="if-a-split-happens" tabindex="-1">If a split happens <a class="header-anchor" href="#if-a-split-happens" aria-label="Permalink to &quot;If a split happens&quot;">​</a></h2><p>Suggested target layout (not committed to):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>soma-backend/</span></span>
<span class="line"><span>├── backend/          # Rust workspace (shared crates + somad)</span></span>
<span class="line"><span>├── xtask/</span></span>
<span class="line"><span>├── deploy/           # Helm charts for somad</span></span>
<span class="line"><span>├── Dockerfile</span></span>
<span class="line"><span>└── .github/workflows/release-server.yml</span></span>
<span class="line"><span>                     # plus a crate-publishing step if the runtime crates ship to a registry</span></span>
<span class="line"><span></span></span>
<span class="line"><span>soma-desktop/</span></span>
<span class="line"><span>├── desktop/          # pnpm workspace + the Tauri app&#39;s src-tauri Rust crates</span></span>
<span class="line"><span>└── .github/workflows/release-desktop.yml</span></span>
<span class="line"><span>                     # consumes the runtime crates from soma-backend (registry or vendored)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>Open decisions before doing this:</p><ul><li>Do the runtime crates ship via a (private) Cargo registry, or get vendored into the desktop repo per release?</li><li>Where do the docs live — one <code>soma-docs</code> repo, or split docs per product?</li><li>Does the desktop repo build a release against arbitrary backend versions, or pin to a known-good set of runtime-crate versions per desktop release?</li></ul><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to &quot;Recommendation&quot;">​</a></h2><p><strong>Do not split now.</strong> The remaining work is small, but there is no concrete pressure (independent release cadences, separate ownership, repo-size pain) that justifies the coordination cost. Revisit when one of those pressures appears.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li><a href="./shared-contracts">Shared Contracts</a> — what crosses the language boundary inside the monorepo today</li><li><a href="./deployment">Deployment</a> — current packaging and release pipelines</li><li><a href="/02-v2">V2 Clarity Plan</a> — the thinking that drove the architectural collapse</li></ul>`,19)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
